using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration; using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationCapabilityDescriptorTests{[Fact]public void Constructs_and_defensively_copies(){var m=new Dictionary<string,string>{{"a","b"}};var d=new AstronomyKnowledgeFoundationCapabilityDescriptor(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x")," c "," n "," d ",0,typeof<IDisposable),typeof(System.IO.MemoryStream),ServiceLifetime.Singleton,m);m["a"]="c";Assert.Equal("c",d.Code);Assert.Equal("b",d.Metadata["a"]);Assert.Throws<NotSupportedException>(()=>((IDictionary<string,string>)d.Metadata).Add("x","y"));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeFoundationCapabilityDescriptor(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x"),"","n","d",0,typeof(IDisposable),typeof(System.IO.MemoryStream),ServiceLifetime.Singleton));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeFoundationCapabilityDescriptor(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x"),"c","n","d",-1,typeof(IDisposable),typeof(System.IO.MemoryStream),ServiceLifetime.Singleton));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeFoundationCapabilityDescriptor(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x"),"c","n","d",0,typeof(Stream),typeof(string),ServiceLifetime.Singleton));}}
